 12→// ParseHookEvent translates a Cursor hook into a normalized lifecycle Event.
 13→// Returns nil if the hook has no lifecycle significance.
 14→func (c *CursorAgent) ParseHookEvent(hookName string, stdin io.Reader) (*agent.Event, error) {
 15→	switch hookName {
 16→	case HookNameSessionStart:
 17→		return c.parseSessionStart(stdin)
 18→	case HookNameBeforeSubmitPrompt:
 19→		return c.parseTurnStart(stdin)
 20→	case HookNameStop:
 21→		return c.parseTurnEnd(stdin)
 22→	case HookNameSessionEnd:
 23→		return c.parseSessionEnd(stdin)
 24→	case HookNamePreCompact:
 25→		return c.parsePreCompact(stdin)
 26→	case HookNameSubagentStart:
 27→		return c.parseSubagentStart(stdin)
 28→	case HookNameSubagentStop:
 29→		return c.parseSubagentStop(stdin)
 30→	default:
 31→		return nil, nil //nolint:nilnil // Unknown hooks have no lifecycle action
 32→	}
 33→}
 34→
 35→// ReadTranscript reads the raw JSONL transcript bytes for a session.
 36→func (c *CursorAgent) ReadTranscript(sessionRef string) ([]byte, error) {
 37→	data, err := os.ReadFile(sessionRef) //nolint:gosec // Path comes from agent hook input
 38→	if err != nil {
 39→		return nil, fmt.Errorf("failed to read transcript: %w", err)
 40→	}
 41→	return data, nil
 42→}
