 50→func (c *CursorAgent) parseSessionStart(stdin io.Reader) (*agent.Event, error) {
 51→	raw, err := agent.ReadAndParseHookInput[sessionInfoRaw](stdin)
 52→	if err != nil {
 53→		return nil, err
 54→	}
 55→	return &agent.Event{
 56→		Type:       agent.SessionStart,
 57→		SessionID:  raw.ConversationID,
 58→		SessionRef: raw.TranscriptPath,
 59→		Timestamp:  time.Now(),
 60→	}, nil
 61→}
 62→
 63→func (c *CursorAgent) parseTurnStart(stdin io.Reader) (*agent.Event, error) {
 64→	raw, err := agent.ReadAndParseHookInput[beforeSubmitPromptInputRaw](stdin)
 65→	if err != nil {
 66→		return nil, err
 67→	}
 68→	return &agent.Event{
 69→		Type:       agent.TurnStart,
 70→		SessionID:  raw.ConversationID,
 71→		SessionRef: raw.TranscriptPath,
 72→		Prompt:     raw.Prompt,
 73→		Timestamp:  time.Now(),
 74→	}, nil
 75→}
