116→func (c *CursorAgent) parseSubagentStart(stdin io.Reader) (*agent.Event, error) {
117→	raw, err := agent.ReadAndParseHookInput[subagentStartHookInputRaw](stdin)
118→	if err != nil {
119→		return nil, err
120→	}
121→	if raw.Task == "" {
122→		return nil, nil //nolint:nilnil // nil event = no lifecycle action
123→	}
124→	return &agent.Event{
125→		Type:            agent.SubagentStart,
126→		SessionID:       raw.ConversationID,
127→		SessionRef:      raw.TranscriptPath,
128→		SubagentID:      raw.SubagentID,
129→		ToolUseID:       raw.SubagentID,
130→		SubagentType:    raw.SubagentType,
131→		TaskDescription: raw.Task,
132→		Timestamp:       time.Now(),
133→	}, nil
134→}
135→
136→func (c *CursorAgent) parseSubagentStop(stdin io.Reader) (*agent.Event, error) {
137→	raw, err := agent.ReadAndParseHookInput[subagentStopHookInputRaw](stdin)
138→	if err != nil {
139→		return nil, err
140→	}
141→	if raw.Task == "" {
142→		return nil, nil //nolint:nilnil // nil event = no lifecycle action
143→	}
144→	event := &agent.Event{
145→		Type:            agent.SubagentEnd,
146→		SessionID:       raw.ConversationID,
147→		SessionRef:      raw.TranscriptPath,
148→		ToolUseID:       raw.SubagentID,
149→		SubagentType:    raw.SubagentType,
150→		TaskDescription: raw.Task,
151→		Timestamp:       time.Now(),
152→		SubagentID:      raw.SubagentID,
153→	}
154→	return event, nil
155→}
