279→func TestParseHookEvent_AllHookTypes(t *testing.T) {
280→	t.Parallel()
281→
282→	testCases := []struct {
283→		hookName      string
284→		expectedType  agent.EventType
285→		expectNil     bool
286→		inputTemplate string
287→	}{
288→		{
289→			hookName:      HookNameSessionStart,
290→			expectedType:  agent.SessionStart,
291→			inputTemplate: `{"session_id": "s1", "transcript_path": "/t"}`,
292→		},
293→		{
294→			hookName:      HookNameBeforeSubmitPrompt,
295→			expectedType:  agent.TurnStart,
296→			inputTemplate: `{"session_id": "s2", "transcript_path": "/t", "prompt": "hi"}`,
297→		},
298→		{
299→			hookName:      HookNameStop,
300→			expectedType:  agent.TurnEnd,
301→			inputTemplate: `{"session_id": "s3", "transcript_path": "/t"}`,
302→		},
303→		{
304→			hookName:      HookNameSessionEnd,
305→			expectedType:  agent.SessionEnd,
306→			inputTemplate: `{"session_id": "s4", "transcript_path": "/t"}`,
307→		},
308→		{
309→			hookName:      HookNameSubagentStart,
310→			expectedType:  agent.SubagentStart,
311→			inputTemplate: `{"conversation_id": "s5", "transcript_path": "/t", "subagent_id": "sub1", "task": "do something"}`,
312→		},
313→		{
314→			hookName:      HookNameSubagentStop,
315→			expectedType:  agent.SubagentEnd,
316→			inputTemplate: `{"conversation_id": "s6", "transcript_path": "/t", "subagent_id": "sub2", "task": "do something"}`,
317→		},
318→	}
319→
320→	for _, tc := range testCases {
321→		t.Run(tc.hookName, func(t *testing.T) {
322→			t.Parallel()
323→
324→			ag := &CursorAgent{}
325→			event, err := ag.ParseHookEvent(tc.hookName, strings.NewReader(tc.inputTemplate))
326→
327→			if err != nil {
328→				t.Fatalf("unexpected error: %v", err)
329→			}
330→
331→			if tc.expectNil {
332→				if event != nil {
333→					t.Errorf("expected nil event, got %+v", event)
334→				}
335→				return
336→			}
337→
338→			if event == nil {
339→				t.Fatal("expected event, got nil")
340→			}
341→			if event.Type != tc.expectedType {
342→				t.Errorf("expected event type %v, got %v", tc.expectedType, event.Type)
343→			}
344→		})
345→	}
346→}
