350→func TestReadTranscript_Success(t *testing.T) {
351→	t.Parallel()
352→	tmpDir := t.TempDir()
353→	transcriptPath := writeSampleTranscript(t, tmpDir)
354→
355→	ag := &CursorAgent{}
356→	data, err := ag.ReadTranscript(transcriptPath)
357→	if err != nil {
358→		t.Fatalf("ReadTranscript() error = %v", err)
359→	}
360→	if len(data) == 0 {
361→		t.Error("ReadTranscript() returned empty data")
362→	}
363→
364→	// Verify it contains the expected Cursor format markers
365→	content := string(data)
366→	if !strings.Contains(content, `"role":"user"`) {
367→		t.Error("transcript missing 'role' field (Cursor uses 'role', not 'type')")
368→	}
369→	if !strings.Contains(content, "<user_query>") {
370→		t.Error("transcript missing <user_query> tags (Cursor wraps user text)")
371→	}
372→}
