 48→// DetectPresence checks if Cursor is configured in the repository.
 49→func (c *CursorAgent) DetectPresence() (bool, error) {
 50→	worktreeRoot, err := paths.WorktreeRoot()
 51→	if err != nil {
 52→		worktreeRoot = "."
 53→	}
 54→
 55→	cursorDir := filepath.Join(worktreeRoot, ".cursor")
 56→	if _, err := os.Stat(cursorDir); err == nil {
 57→		return true, nil
 58→	}
 59→	return false, nil
