151→// ChunkTranscript splits a JSONL transcript at line boundaries.
152→func (c *CursorAgent) ChunkTranscript(content []byte, maxSize int) ([][]byte, error) {
153→	chunks, err := agent.ChunkJSONL(content, maxSize)
154→	if err != nil {
