 17→	_ agent.HookSupport = (*CursorAgent)(nil)
 18→)
 19→
 20→// Cursor hook names - these become subcommands under `entire hooks cursor`
 21→const (
 22→	HookNameSessionStart       = "session-start"
 23→	HookNameSessionEnd         = "session-end"
 24→	HookNameBeforeSubmitPrompt = "before-submit-prompt"
 25→	HookNameStop               = "stop"
 26→	HookNamePreCompact         = "pre-compact"
 27→	HookNameSubagentStart      = "subagent-start"
 28→	HookNameSubagentStop       = "subagent-stop"
 29→)
 30→
 31→// HooksFileName is the hooks file used by Cursor.
 32→const HooksFileName = "hooks.json"
 33→
 34→// entireHookPrefixes are command prefixes that identify Entire hooks
 35→var entireHookPrefixes = []string{
 36→	"entire ",
 37→	"go run ${CURSOR_PROJECT_DIR}/cmd/entire/main.go ",
 38→}
 39→
 40→// HookNames returns the hook verbs Cursor supports.
 41→// These become subcommands: entire hooks cursor <verb>
 42→func (c *CursorAgent) HookNames() []string {
 43→	return []string{
 44→		HookNameSessionStart,
 45→		HookNameSessionEnd,
 46→		HookNameBeforeSubmitPrompt,
 47→		HookNameStop,
 48→		HookNamePreCompact,
 49→		HookNameSubagentStart,
 50→		HookNameSubagentStop,
 51→	}
 52→}
 53→
 54→// InstallHooks installs Cursor hooks in .cursor/hooks.json.
 55→// If force is true, removes existing Entire hooks before installing.
 56→// Returns the number of hooks installed.
 57→// Unknown top-level fields and hook types are preserved on round-trip.
 58→func (c *CursorAgent) InstallHooks(localDev bool, force bool) (int, error) {
 59→	worktreeRoot, err := paths.WorktreeRoot()
 60→	if err != nil {
 61→		worktreeRoot = "."
 62→	}
 63→
 64→	hooksPath := filepath.Join(worktreeRoot, ".cursor", HooksFileName)
 65→
 66→	// Use raw maps to preserve unknown fields on round-trip
 67→	var rawFile map[string]json.RawMessage
 68→	var rawHooks map[string]json.RawMessage
 69→
 70→	existingData, readErr := os.ReadFile(hooksPath) //nolint:gosec // path is constructed from repo root + fixed path
 71→	if readErr == nil {
 72→		if err := json.Unmarshal(existingData, &rawFile); err != nil {
 73→			return 0, fmt.Errorf("failed to parse existing "+HooksFileName+": %w", err)
 74→		}
 75→		if hooksRaw, ok := rawFile["hooks"]; ok {
 76→			if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
 77→				return 0, fmt.Errorf("failed to parse hooks in "+HooksFileName+": %w", err)
 78→			}
 79→		}
 80→		if _, ok := rawFile["version"]; !ok {
 81→			rawFile["version"] = json.RawMessage(`1`)
 82→		}
 83→	} else {
 84→		rawFile = map[string]json.RawMessage{
 85→			"version": json.RawMessage(`1`),
 86→		}
 87→	}
 88→
 89→	if rawHooks == nil {
 90→		rawHooks = make(map[string]json.RawMessage)
 91→	}
 92→
 93→	// Parse only the hook types we manage
 94→	var sessionStart, sessionEnd, beforeSubmitPrompt, stop, preCompact, subagentStart, subagentStop []CursorHookEntry
 95→	parseCursorHookType(rawHooks, "sessionStart", &sessionStart)
 96→	parseCursorHookType(rawHooks, "sessionEnd", &sessionEnd)
 97→	parseCursorHookType(rawHooks, "beforeSubmitPrompt", &beforeSubmitPrompt)
 98→	parseCursorHookType(rawHooks, "stop", &stop)
 99→	parseCursorHookType(rawHooks, "preCompact", &preCompact)
100→	parseCursorHookType(rawHooks, "subagentStart", &subagentStart)
101→	parseCursorHookType(rawHooks, "subagentStop", &subagentStop)
102→
103→	// If force is true, remove all existing Entire hooks first
104→	if force {
105→		sessionStart = removeEntireHooks(sessionStart)
106→		sessionEnd = removeEntireHooks(sessionEnd)
107→		beforeSubmitPrompt = removeEntireHooks(beforeSubmitPrompt)
108→		stop = removeEntireHooks(stop)
109→		preCompact = removeEntireHooks(preCompact)
110→		subagentStart = removeEntireHooks(subagentStart)
111→		subagentStop = removeEntireHooks(subagentStop)
112→	}
113→
114→	// Define hook commands
115→	var cmdPrefix string
116→	if localDev {
117→		cmdPrefix = "go run ${CURSOR_PROJECT_DIR}/cmd/entire/main.go hooks cursor "
118→	} else {
119→		cmdPrefix = "entire hooks cursor "
120→	}
121→
122→	sessionStartCmd := cmdPrefix + HookNameSessionStart
123→	sessionEndCmd := cmdPrefix + HookNameSessionEnd
124→	beforeSubmitPromptCmd := cmdPrefix + HookNameBeforeSubmitPrompt
125→	stopCmd := cmdPrefix + HookNameStop
126→	preCompactCmd := cmdPrefix + HookNamePreCompact
127→	subagentStartCmd := cmdPrefix + HookNameSubagentStart
128→	subagentEndCmd := cmdPrefix + HookNameSubagentStop
129→
130→	count := 0
131→
132→	// Add hooks if they don't exist
133→	if !hookCommandExists(sessionStart, sessionStartCmd) {
134→		sessionStart = append(sessionStart, CursorHookEntry{Command: sessionStartCmd})
135→		count++
136→	}
137→	if !hookCommandExists(sessionEnd, sessionEndCmd) {
138→		sessionEnd = append(sessionEnd, CursorHookEntry{Command: sessionEndCmd})
139→		count++
140→	}
141→	if !hookCommandExists(beforeSubmitPrompt, beforeSubmitPromptCmd) {
142→		beforeSubmitPrompt = append(beforeSubmitPrompt, CursorHookEntry{Command: beforeSubmitPromptCmd})
143→		count++
144→	}
145→	if !hookCommandExists(stop, stopCmd) {
146→		stop = append(stop, CursorHookEntry{Command: stopCmd})
147→		count++
148→	}
149→	if !hookCommandExists(preCompact, preCompactCmd) {
150→		preCompact = append(preCompact, CursorHookEntry{Command: preCompactCmd})
151→		count++
152→	}
153→	if !hookCommandExists(subagentStart, subagentStartCmd) {
154→		subagentStart = append(subagentStart, CursorHookEntry{Command: subagentStartCmd})
155→		count++
156→	}
157→	if !hookCommandExists(subagentStop, subagentEndCmd) {
158→		subagentStop = append(subagentStop, CursorHookEntry{Command: subagentEndCmd})
159→		count++
160→	}
161→
162→	if count == 0 {
163→		return 0, nil
164→	}
165→
166→	// Marshal modified hook types back into rawHooks
167→	marshalCursorHookType(rawHooks, "sessionStart", sessionStart)
168→	marshalCursorHookType(rawHooks, "sessionEnd", sessionEnd)
169→	marshalCursorHookType(rawHooks, "beforeSubmitPrompt", beforeSubmitPrompt)
170→	marshalCursorHookType(rawHooks, "stop", stop)
171→	marshalCursorHookType(rawHooks, "preCompact", preCompact)
172→	marshalCursorHookType(rawHooks, "subagentStart", subagentStart)
173→	marshalCursorHookType(rawHooks, "subagentStop", subagentStop)
174→
175→	// Marshal hooks and update raw file
176→	hooksJSON, err := json.Marshal(rawHooks)
177→	if err != nil {
178→		return 0, fmt.Errorf("failed to marshal hooks: %w", err)
179→	}
180→	rawFile["hooks"] = hooksJSON
181→
182→	// Write to file
183→	if err := os.MkdirAll(filepath.Dir(hooksPath), 0o750); err != nil {
184→		return 0, fmt.Errorf("failed to create .cursor directory: %w", err)
185→	}
186→
187→	output, err := jsonutil.MarshalIndentWithNewline(rawFile, "", "  ")
188→	if err != nil {
189→		return 0, fmt.Errorf("failed to marshal "+HooksFileName+": %w", err)
190→	}
191→
192→	if err := os.WriteFile(hooksPath, output, 0o600); err != nil {
193→		return 0, fmt.Errorf("failed to write "+HooksFileName+": %w", err)
194→	}
195→
196→	return count, nil
197→}
