199→// UninstallHooks removes Entire hooks from Cursor HooksFileName.
200→// Unknown top-level fields and hook types are preserved on round-trip.
201→func (c *CursorAgent) UninstallHooks() error {
202→	worktreeRoot, err := paths.WorktreeRoot()
203→	if err != nil {
204→		worktreeRoot = "."
205→	}
206→	hooksPath := filepath.Join(worktreeRoot, ".cursor", HooksFileName)
207→	data, err := os.ReadFile(hooksPath) //nolint:gosec // path is constructed from repo root + fixed path
208→	if err != nil {
209→		return nil //nolint:nilerr // No hooks file means nothing to uninstall
210→	}
211→
212→	var rawFile map[string]json.RawMessage
213→	if err := json.Unmarshal(data, &rawFile); err != nil {
214→		return fmt.Errorf("failed to parse "+HooksFileName+": %w", err)
215→	}
216→
217→	var rawHooks map[string]json.RawMessage
218→	if hooksRaw, ok := rawFile["hooks"]; ok {
219→		if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
220→			return fmt.Errorf("failed to parse hooks in "+HooksFileName+": %w", err)
221→		}
222→	}
223→	if rawHooks == nil {
224→		rawHooks = make(map[string]json.RawMessage)
225→	}
226→
227→	// Parse only the hook types we manage
228→	var sessionStart, sessionEnd, beforeSubmitPrompt, stop, preCompact, subagentStart, subagentStop []CursorHookEntry
229→	parseCursorHookType(rawHooks, "sessionStart", &sessionStart)
230→	parseCursorHookType(rawHooks, "sessionEnd", &sessionEnd)
231→	parseCursorHookType(rawHooks, "beforeSubmitPrompt", &beforeSubmitPrompt)
232→	parseCursorHookType(rawHooks, "stop", &stop)
233→	parseCursorHookType(rawHooks, "preCompact", &preCompact)
234→	parseCursorHookType(rawHooks, "subagentStart", &subagentStart)
235→	parseCursorHookType(rawHooks, "subagentStop", &subagentStop)
236→
237→	// Remove Entire hooks from all hook types
238→	sessionStart = removeEntireHooks(sessionStart)
239→	sessionEnd = removeEntireHooks(sessionEnd)
240→	beforeSubmitPrompt = removeEntireHooks(beforeSubmitPrompt)
241→	stop = removeEntireHooks(stop)
242→	preCompact = removeEntireHooks(preCompact)
243→	subagentStart = removeEntireHooks(subagentStart)
244→	subagentStop = removeEntireHooks(subagentStop)
245→
246→	// Marshal modified hook types back into rawHooks
247→	marshalCursorHookType(rawHooks, "sessionStart", sessionStart)
248→	marshalCursorHookType(rawHooks, "sessionEnd", sessionEnd)
249→	marshalCursorHookType(rawHooks, "beforeSubmitPrompt", beforeSubmitPrompt)
250→	marshalCursorHookType(rawHooks, "stop", stop)
251→	marshalCursorHookType(rawHooks, "preCompact", preCompact)
252→	marshalCursorHookType(rawHooks, "subagentStart", subagentStart)
253→	marshalCursorHookType(rawHooks, "subagentStop", subagentStop)
254→
255→	// Marshal hooks back (preserving unknown hook types)
256→	if len(rawHooks) > 0 {
257→		hooksJSON, err := json.Marshal(rawHooks)
258→		if err != nil {
259→			return fmt.Errorf("failed to marshal hooks: %w", err)
260→		}
261→		rawFile["hooks"] = hooksJSON
262→	} else {
263→		delete(rawFile, "hooks")
264→	}
265→
266→	// Write back
267→	output, err := jsonutil.MarshalIndentWithNewline(rawFile, "", "  ")
268→	if err != nil {
269→		return fmt.Errorf("failed to marshal "+HooksFileName+": %w", err)
270→	}
271→
272→	if err := os.WriteFile(hooksPath, output, 0o600); err != nil {
273→		return fmt.Errorf("failed to write "+HooksFileName+": %w", err)
274→	}
275→	return nil
276→}
