304→// GetSupportedHooks returns the hook types Cursor supports.
305→func (c *CursorAgent) GetSupportedHooks() []agent.HookType {
306→	return []agent.HookType{
307→		agent.HookSessionStart,
308→		agent.HookSessionEnd,
309→		agent.HookUserPromptSubmit,
310→		agent.HookStop,
311→		agent.HookPreToolUse,
312→		agent.HookPostToolUse,
313→	}
314→}
