316→// parseCursorHookType parses a specific hook type from rawHooks into the target slice.
317→// Silently ignores parse errors (leaves target unchanged).
318→func parseCursorHookType(rawHooks map[string]json.RawMessage, hookType string, target *[]CursorHookEntry) {
319→	if data, ok := rawHooks[hookType]; ok {
320→		//nolint:errcheck,gosec // Intentionally ignoring parse errors - leave target as nil/empty
321→		json.Unmarshal(data, target)
322→	}
323→}
324→
325→// marshalCursorHookType marshals a hook type back into rawHooks.
326→// If the slice is empty, removes the key from rawHooks.
327→func marshalCursorHookType(rawHooks map[string]json.RawMessage, hookType string, entries []CursorHookEntry) {
328→	if len(entries) == 0 {
329→		delete(rawHooks, hookType)
330→		return
331→	}
332→	data, err := json.Marshal(entries)
333→	if err != nil {
334→		return // Silently ignore marshal errors (shouldn't happen)
335→	}
336→	rawHooks[hookType] = data
337→}
338→
339→// Helper functions for hook management
340→
341→func hookCommandExists(entries []CursorHookEntry, command string) bool {
342→	for _, entry := range entries {
343→		if entry.Command == command {
344→			return true
345→		}
346→	}
347→	return false
348→}
349→
350→func isEntireHook(command string) bool {
351→	for _, prefix := range entireHookPrefixes {
352→		if strings.HasPrefix(command, prefix) {
353→			return true
354→		}
355→	}
356→	return false
357→}
358→
359→func hasEntireHook(entries []CursorHookEntry) bool {
360→	for _, entry := range entries {
361→		if isEntireHook(entry.Command) {
362→			return true
363→		}
364→	}
365→	return false
366→}
367→
368→func removeEntireHooks(entries []CursorHookEntry) []CursorHookEntry {
369→	result := make([]CursorHookEntry, 0, len(entries))
370→	for _, entry := range entries {
371→		if !isEntireHook(entry.Command) {
372→			result = append(result, entry)
373→		}
374→	}
375→	return result
376→}
