// resolveSessionRef computes the transcript path from WorktreeRoot + session ID,
// instead of trusting the hook-provided transcript_path (which is sometimes null).
func (c *CursorAgent) resolveSessionRef(conversationID string) string {
	repoRoot, err := paths.WorktreeRoot()
	if err != nil {
		return ""
	}
	sessionDir, err := c.GetSessionDir(repoRoot)
	if err != nil {
		return ""
	}
	return c.ResolveSessionFile(sessionDir, conversationID)
}

