 13→// ParseHookEvent translates a Cursor hook into a normalized lifecycle Event.
 14→// Returns nil if the hook has no lifecycle significance.
 15→func (c *CursorAgent) ParseHookEvent(hookName string, stdin io.Reader) (*agent.Event, error) {
 16→	switch hookName {
 17→	case HookNameSessionStart:
 18→		return c.parseSessionStart(stdin)
 19→	case HookNameBeforeSubmitPrompt:
 20→		return c.parseTurnStart(stdin)
 21→	case HookNameStop:
 22→		return c.parseTurnEnd(stdin)
 23→	case HookNameSessionEnd:
 24→		return c.parseSessionEnd(stdin)
 25→	case HookNamePreCompact:
 26→		return c.parsePreCompact(stdin)
 27→	case HookNameSubagentStart:
 28→		return c.parseSubagentStart(stdin)
 29→	case HookNameSubagentStop:
 30→		return c.parseSubagentStop(stdin)
 31→	default:
 32→		return nil, nil //nolint:nilnil // Unknown hooks have no lifecycle action
 33→	}
 34→}
 35→
 36→// ReadTranscript reads the raw JSONL transcript bytes for a session.
 37→func (c *CursorAgent) ReadTranscript(sessionRef string) ([]byte, error) {
 38→	data, err := os.ReadFile(sessionRef) //nolint:gosec // Path comes from agent hook input
 39→	if err != nil {
 40→		return nil, fmt.Errorf("failed to read transcript: %w", err)
 41→	}
 42→	return data, nil
 43→}
