 45→// Note: CursorAgent does NOT implement TranscriptAnalyzer. Cursor's transcript
 46→// format does not contain tool_use blocks that would allow extracting modified
 47→// files. File detection relies on git status instead.
 48→
 49→// resolveSessionRef computes the transcript path from WorktreeRoot + session ID,
 50→// instead of trusting the hook-provided transcript_path (which is sometimes null).
 51→func (c *CursorAgent) resolveSessionRef(conversationID string) string {
 52→	repoRoot, err := paths.WorktreeRoot()
 53→	if err != nil {
 54→		return ""
 55→	}
 56→	sessionDir, err := c.GetSessionDir(repoRoot)
 57→	if err != nil {
 58→		return ""
 59→	}
 60→	return c.ResolveSessionFile(sessionDir, conversationID)
 61→}
